// Mark the current face as processed to avoid cycles
face->info().processed = true;

// Get the vertices of the current edge
Triangulation::Vertex_handle v1 = face->vertex((edge + 1) % 3);
Triangulation::Vertex_handle v2 = face->vertex((edge + 2) % 3);

// Check if the current edge is constrained (boundary edge)
if (triangulation.is_constrained(Triangulation::Edge(face, edge)))
{
    // Add the vertices to the output list
    vertices.push_back(v1);
    vertices.push_back(v2);
    return;
}

// If not constrained, move to the adjacent face
Triangulation::Face_handle neighbor = face->neighbor(edge);

// Check if the neighbor face exists and is interior but not processed
if (neighbor != Triangulation::Face_handle() &&
    neighbor->info().interior &&
    !neighbor->info().processed)
{
    // Find the index of the edge in the neighbor face
    int neighbor_edge = neighbor->index(face);

    // Recursively collect boundary vertices from the neighbor face
    get_face_boundary_vertices(neighbor, neighbor_edge, vertices);
}

